<svelte:options runes={true} />

<script lang="ts">
  // Project metadata and column administration.
  import { confirmAdminColumnArchive, confirmAdminColumnCreate, confirmAdminColumnMove, confirmAdminColumnSave, confirmAdminProjectArchive, confirmAdminProjectSave, loadAdminColumns, loadProjectAdmin, setAdminProjectDraft } from '../../admin';
  import { stateLabels } from '../../constants';
  import { admin } from '../../state/admin.svelte';
</script>

<section class="settings-section admin-section" aria-labelledby="project-admin-heading">
  <div class="settings-section-heading">
    <div><span class="eyebrow">Workspace administration</span><h2 id="project-admin-heading">Projects &amp; columns</h2><p>Rename projects, tune their descriptions and colors, and keep the board’s semantic columns in a safe order.</p></div>
    <span class="admin-lock-badge">Admin only</span>
  </div>
  {#if admin.adminError}<div class="inline-alert error" role="alert"><span>!</span>{admin.adminError}<button class="text-button" type="button" on:click={loadProjectAdmin}>Retry</button></div>{/if}
  {#if admin.adminLoading}<div class="list-skeleton" aria-label="Loading project administration"><div></div><div></div></div>
  {:else if !admin.adminProjects.length}<div class="empty-state compact-empty"><div class="empty-icon">◎</div><h3>No projects yet</h3><p>Create a project first, then its columns can be managed here.</p></div>
  {:else if admin.adminProject}
    <div class="admin-project-picker"><label for="admin-project-select">Project<select id="admin-project-select" bind:value={admin.adminProjectId} on:change={() => { const selected = admin.adminProjects.find((project) => project.id === admin.adminProjectId); if (selected) { setAdminProjectDraft(selected); void loadAdminColumns(selected.id); } }}><option value="" disabled>Choose a project</option>{#each admin.adminProjects as project}<option value={project.id}>{project.key} · {project.name}{#if project.archived_at} · archived{/if}</option>{/each}</select></label><span class:admin-status-archived={Boolean(admin.adminProject.archived_at)} class="admin-status">{admin.adminProject.archived_at ? 'Archived' : 'Active'}</span></div>
    <form class="admin-project-form" on:submit|preventDefault={confirmAdminProjectSave}>
      <div class="form-row"><label>Project name<input bind:value={admin.adminProjectName} maxlength="200" /></label><label>Accent color<input class="color-input" type="color" bind:value={admin.adminProjectColor} /></label></div>
      <label>Description <span class="optional">Optional</span><textarea rows="3" maxlength="20000" bind:value={admin.adminProjectDescription}></textarea></label>
      <label>Checklist completion policy<select bind:value={admin.adminChecklistPolicy}><option value="warn">Warn · allow completion with open items</option><option value="require">Require · block completion until all items are checked</option></select><span class="field-hint">Applies to task moves, bug resolution, and columns remapped to Done.</span></label>
      <div class="form-actions"><button class="button quiet-button" type="button" on:click={() => confirmAdminProjectArchive(admin.adminProject!)}>{admin.adminProject.archived_at ? 'Restore project' : 'Archive project'}</button><button class="button primary" type="submit" disabled={admin.adminSaving || !admin.adminProjectName.trim()}>{#if admin.adminSaving}<span class="button-spinner"></span>{/if}Save project</button></div>
    </form>
    <div class="admin-columns-heading"><div><h3>Columns</h3><p>Each semantic state must keep one live mapping. Archiving a column moves its tasks to another live column with the same state.</p></div></div>
    <form class="admin-column-create" on:submit|preventDefault={confirmAdminColumnCreate}><label>New column name<input bind:value={admin.adminColumnName} maxlength="100" placeholder="Review" /></label><label>Semantic mapping<select bind:value={admin.adminColumnState}>{#each Object.entries(stateLabels) as [state, label]}<option value={state}>{label}</option>{/each}</select></label><button class="button primary" type="submit" disabled={admin.adminColumnCreating || !admin.adminColumnName.trim()}>＋ Add column</button></form>
    {#if admin.adminColumnsLoading}<div class="list-skeleton" aria-label="Loading columns"><div></div></div>
    {:else if !admin.adminColumns.length}<p class="admin-empty-note">No columns found for this project.</p>
    {:else}<div class="admin-column-list" aria-label="Project columns">{#each admin.adminColumns as column (column.id)}<article class:archived={Boolean(column.archived_at)} class="admin-column-row"><div class="admin-column-grip" aria-hidden="true">⋮⋮</div><div class="admin-column-fields"><label><span class="sr-only">Column name</span><input aria-label={`Column name for ${column.name}`} bind:value={() => column.name, (value) => admin.adminColumns = admin.adminColumns.map((item) => item.id === column.id ? { ...item, name: value } : item)} maxlength="100" /></label><label><span class="sr-only">Semantic mapping</span><select aria-label={`Semantic mapping for ${column.name}`} bind:value={() => column.semantic_state, (value) => admin.adminColumns = admin.adminColumns.map((item) => item.id === column.id ? { ...item, semantic_state: value } : item)}>{#each Object.entries(stateLabels) as [state, label]}<option value={state}>{label}</option>{/each}</select></label><span class="admin-column-position">#{column.position + 1}</span></div><div class="admin-column-actions"><button class="icon-button tiny" type="button" aria-label={`Move ${column.name} up`} disabled={Boolean(column.archived_at) || admin.adminColumnSaving === column.id || (admin.adminLiveColumnIndexes.get(column.id) ?? -1) <= 0} on:click={() => confirmAdminColumnMove(column, Math.max(0, column.position - 1))}>↑</button><button class="icon-button tiny" type="button" aria-label={`Move ${column.name} down`} disabled={Boolean(column.archived_at) || admin.adminColumnSaving === column.id || (admin.adminLiveColumnIndexes.get(column.id) ?? -1) >= admin.adminLiveColumns.length - 1} on:click={() => confirmAdminColumnMove(column, column.position + 1)}>↓</button><button class="button quiet-button compact-button" type="button" disabled={admin.adminColumnSaving === column.id || !column.name.trim()} on:click={() => confirmAdminColumnSave(column)}>{admin.adminColumnSaving === column.id ? 'Saving…' : 'Save'}</button><button class="text-button compact-button" type="button" disabled={admin.adminColumnSaving === column.id} on:click={() => confirmAdminColumnArchive(column)}>{column.archived_at ? 'Restore' : 'Archive'}</button></div></article>{/each}</div>{/if}
  {/if}
</section>
